# Surah Al-A'raf (chapter 7) — part 6: ayat 51-60 (IDs 1005-1014)
SURAH = 7

ENTRIES = {
1005: (
"وہ لوگ — جنہوں نے اپنے دین کو — کھیل اور تفریح بنا لیا — اور انہیں — دنیا کی زندگی نے غرور میں مبتلا کیا — پس — آج — ہم انہیں ان کی طرح — فراموش کر دیں گے — جس طرح انہوں نے — اس دن کی ملاقات — کو فراموش کیا — اور جس طرح وہ — ہماری آیات کا انکار کرتے تھے",
"""۱۔ دین کو تفریح بنانا — سب سے بڑا خسارہ۔
۲۔ ’’الَّذِينَ اتَّخَذُوا دِينَهُمْ لَهْوًا وَلَعِبًا وَغَرَّتْهُمُ الْحَيَاۃُ الدُّنْيَا فَالْيَوْمَ نَنسَاهُمْ كَمَا نَسُوا لِقَاءَ يَوْمِهِمْ هَٰذَا وَمَا كَانُوا بِآيَاتِنَا يَجْحَدُونَ‘‘ — وہ لوگ — جنہوں نے اپنے دین کو — کھیل اور تفریح بنا لیا — اور انہیں — دنیا کی زندگی نے غرور میں مبتلا کیا — پس — آج — ہم انہیں ان کی طرح — فراموش کر دیں گے — جس طرح انہوں نے — اس دن کی ملاقات — کو فراموش کیا — اور جس طرح وہ — ہماری آیات کا انکار کرتے تھے — یعنی جو دین کو ہنسی میں اڑائے — آخرت میں — اللہ کے لطف اور رحمت سے محروم ہوں گے۔
۳۔ عملی سبق: دین — سنجیدہ ذمہ داری ہے؛ اسے ہنسی نہ سمجھو۔"""
),
1006: (
"اور بے شک — ہم — ان کے پاس — ایک کتاب لائے — جس کو ہم — علم کے ساتھ تفصیل سے بیان کیا — ہدایت اور رحمت — اس قوم کے لیے جو ایمان لائے",
"""۱۔ قرآن — علم اور رحمت کا ذریعہ۔
۲۔ ’’وَلَقَدْ جِئْنَاهُم بِكِتَابٍ فَصَّلْنَاهُ عَلَىٰ عِلْمٍ هُدًى وَرَحْمَۃً لِّقَوْمٍ يُؤْمِنُونَ‘‘ — اور بے شک — ہم — ان کے پاس — ایک کتاب لائے — جس کو ہم — علم کے ساتھ تفصیل سے بیان کیا — ہدایت اور رحمت — اس قوم کے لیے جو ایمان لائے — یعنی قرآن — علم پر مبنی — ہدایت اور رحمت کی کتاب ہے۔
۳۔ عملی سبق: قرآن کو علم اور ایمان سے پڑھو؛ یہی رحمت کا سرچشمہ ہے۔"""
),
1007: (
"کیا وہ — اس کی — تعبیر — کا انتظار کر رہے ہیں — جس دن — اس کی تعبیر آئے گی — تو جنہوں نے اسے پہلے فراموش کیا تھا — کہیں گے — بے شک ہمارے رب کے رسول — حق لے کر آئے تھے — تو کیا — ہمارے — سفارش کرنے والے — ہیں جو — ہماری سفارش کریں — یا ہم — واپس بھیجے جائیں — تو وہ عمل کریں — اس — سے — جو — ہم کرتے تھے — بے شک انہوں نے — اپنا نقصان کیا — اور ان سے — گم ہو گیا — جو وہ گھڑتے تھے",
"""۱۔ آخرت میں — ہر حقیقت — بے نقاب۔
۲۔ ’’هَلْ يَنظُرُونَ إِلَّا تَأْوِيلَهُ يَوْمَ يَأْتِي تَأْوِيلُهُ يَقُولُ الَّذِينَ نَسُوهُ مِن قَبْلُ قَدْ جَاءَتْ رُسُلُ رَبِّنَا بِالْحَقِّ فَهَلْ لَنَا مِن شُفَعَاءَ فَيَشْفَعُوا لَنَا أَوْ نُرَدُّ فَنَعْمَلَ غَيْرَ الَّذِي كُنَّا نَعْمَلُ قَدْ خَسِرُوا أَنفُسَهُمْ وَضَلَّ عَنْهُم مَّا كَانُوا يَفْتَرُونَ‘‘ — کیا وہ — اس کی — تعبیر — کا انتظار کر رہے ہیں — جس دن — اس کی تعبیر آئے گی — تو جنہوں نے اسے پہلے فراموش کیا تھا — کہیں گے — بے شک ہمارے رب کے رسول — حق لے کر آئے تھے — تو کیا — ہمارے — سفارش کرنے والے — ہیں جو — ہماری سفارش کریں — یا ہم — واپس بھیجے جائیں — تو وہ عمل کریں — اس — سے — جو — ہم کرتے تھے — بے شک انہوں نے — اپنا نقصان کیا — اور ان سے — گم ہو گیا — جو وہ گھڑتے تھے — یعنی قیامت کی حقیقت — ان کے افترا کو مٹا دے گی۔
۳۔ شیعہ عقائد میں شفاعت — اہلِ بیتؑ اور صالحین کے ذریعے اللہ کی اجازت سے ممکن ہے — شفاعت اللہ کی اجازت کے بغیر کسی کو حاصل نہیں
۴۔ عملی سبق: قیامت — حقیقی ہے؛ آج ہی اپنا ایمان مضبوط کرو۔"""
),
1008: (
"بے شک تمہارا رب — اللہ ہے — جس نے — چھ دنوں میں — آسمان اور زمین بنائے — پھر — عرش پر استواء کیا — رات — دن — پر — ڈھانپتا ہے — اور اسے — جلدی طلب کرتی ہے — اور — سورج — چاند — اور ستارے — اس کے حکم — کے تابع ہیں — خبردار — اسی کا — تخلیق اور — حکم ہے — تبارک اللہ — رب العالمین",
"""۱۔ اللہ — کائنات کا خالق اور مالک۔
۲۔ ’’إِنَّ رَبَّكُمُ اللَّهُ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ فِي سِتَّۃِ أَيَّامٍ ثُمَّ اسْتَوَىٰ عَلَى الْعَرْشِ يُغْشِي اللَّيْلَ النَّهَارَ يَطْلُبُهُ حَثِيثًا وَالشَّمْسَ وَالْقَمَرَ وَالنُّجُومَ مُسَخَّرَاتٍ بِأَمْرِهِ أَلَا لَهُ الْخَلْقُ وَالْأَمْرُ تَبَارَكَ اللَّهُ رَبُّ الْعَالَمِينَ‘‘ — بے شک تمہارا رب — اللہ ہے — جس نے — چھ دنوں میں — آسمان اور زمین بنائے — پھر — عرش پر استواء کیا — رات — دن — پر — ڈھانپتا ہے — اور اسے — جلدی طلب کرتی ہے — اور — سورج — چاند — اور ستارے — اس کے حکم — کے تابع ہیں — خبردار — اسی کا — تخلیق اور — حکم ہے — تبارک اللہ — رب العالمین — یعنی کائنات کا ہر نظام — اللہ کے حکم کے تابع ہے — اور اسی کی تخلیق و تدبیر ہے۔
۳۔ عملی سبق: کائنات کا خالق — صرف اللہ ہے؛ عبادت صرف اسی کی جائے۔"""
),
1009: (
"اپنے رب کو — عاجزی — اور خفیہ طور پر پکارو — بے شک — وہ — حد سے بڑھنے والوں کو — پسند نہیں کرتا",
"""۱۔ دعا — عاجزی اور خفیہ طور پر — اللہ کی پسند۔
۲۔ ’’ادْعُوا رَبَّكُمْ تَضَرُّعًا وَخُفْيَۃً إِنَّهُ لَا يُحِبُّ الْمُعْتَدِينَ‘‘ — اپنے رب کو — عاجزی — اور خفیہ طور پر پکارو — بے شک — وہ — حد سے بڑھنے والوں کو — پسند نہیں کرتا — یعنی دعا میں عاجزی اور خاموشی — اللہ کو پسند ہے؛ چیخ کر مانگنا — یا دکھاوا — ناپسند ہے۔
۳۔ عملی سبق: دعا — سچے دل سے کرو؛ دکھاوے سے بچو۔"""
),
1010: (
"اور زمین میں — اس کی اصلاح کے بعد — فساد نہ کرو — اور اسے — خوف اور — امید کے ساتھ پکارو — بے شک اللہ کی رحمت — نیکوکاروں کے قریب ہے",
"""۱۔ فساد فی الارض — سب سے بڑا جرم۔
۲۔ ’’وَلَا تُفْسِدُوا فِي الْأَرْضِ بَعْدَ إِصْلَاحِهَا وَادْعُوهُ خَوْفًا وَطَمَعًا إِنَّ رَحْمَتَ اللَّهِ قَرِيبٌ مِّنَ الْمُحْسِنِينَ‘‘ — اور زمین میں — اس کی اصلاح کے بعد — فساد نہ کرو — اور اسے — خوف اور — امید کے ساتھ پکارو — بے شک اللہ کی رحمت — نیکوکاروں کے قریب ہے — یعنی فساد سے بچو — اور اللہ سے خوف و امید دونوں کے ساتھ — دعا کرو۔
۳۔ عملی سبق: اپنے علاقے میں — فساد کی بجائے اصلاح میں حصہ ڈالو۔"""
),
1011: (
"اور — وہی ہے جو — اپنی رحمت سے پہلے — ہوائیں بھیجتا ہے — ہوا کے خوش اسلوب — یہاں تک کہ — جب — وہ — بادل — اٹھا لائیں — بھاری — تو ہم — اسے — ایک مردہ بستی کی طرف بھیجتے ہیں — پس — اس سے پانی اتارتے ہیں — پس — اس — سے ہر قسم کے پھل — نکالتے ہیں — اس طرح — ہم مردوں کو — زندہ کریں گے — شاید — تم — نصیحت حاصل کرو",
"""۱۔ بارش — رحمت — اور مردوں کو زندہ کرنے کی دلیل۔
۲۔ ’’وَهُوَ الَّذِي يُرْسِلُ الرِّيَاحَ بُشْرًا بَيْنَ يَدَيْ رَحْمَتِهِ حَتَّىٰ إِذَا أَقَلَّتْ سَحَابًا ثِقَالًا سُقْنَاهُ لِبَلَدٍ مَّيِّتٍ فَأَنزَلْنَا بِهِ الْمَاءَ فَأَخْرَجْنَا بِهِ مِن كُلِّ الثَّمَرَاتِ كَذَٰلِكَ نُخْرِجُ الْمَوْتَىٰ لَعَلَّكُمْ تَذَكَّرُونَ‘‘ — اور — وہی ہے جو — اپنی رحمت سے پہلے — ہوائیں بھیجتا ہے — ہوا کے خوش اسلوب — یہاں تک کہ — جب — وہ — بادل — اٹھا لائیں — بھاری — تو ہم — اسے — ایک مردہ بستی کی طرف بھیجتے ہیں — پس — اس سے پانی اتارتے ہیں — پس — اس — سے ہر قسم کے پھل — نکالتے ہیں — اس طرح — ہم مردوں کو — زندہ کریں گے — شاید — تم — نصیحت حاصل کرو — یعنی بارش کا نظام — قیامت کے حشر کی واضح مثال ہے۔
۳۔ عملی سبق: بارش اور پھل — اللہ کی رحمت کی نشانیاں ہیں؛ شکر کرو۔"""
),
1012: (
"اور — پاکیزہ بستی — اس کا نبات — اس کے رب کے حکم سے — نکلتا ہے — اور — جس — کی — زمین — خراب/فاسد ہے — وہ — نکلتی ہے — نہیں — مگر — برا طرح — اسی طرح — ہم — آیات کو مختلف — انداز میں — ان لوگوں کے لیے بیان کرتے ہیں — جو شکر کریں",
"""۱۔ پاکیزہ سرزمین — اچھی نکالی — اور فاسد زمین — بری نکالی — ایمان کی مثال۔
۲۔ ’’وَالْبَلَدُ الطَّيِّبُ يَخْرُجُ نَبَاتُهُ بِإِذْنِ رَبِّهِ وَالَّذِي خَبُثَ لَا يَخْرُجُ إِلَّا نَكِدًا كَذَٰلِكَ نُصَرِّفُ الْآيَاتِ لِقَوْمٍ يَشْكُرُونَ‘‘ — اور — پاکیزہ بستی — اس کا نبات — اس کے رب کے حکم سے — نکلتا ہے — اور — جس — کی — زمین — خراب/فاسد ہے — وہ — نکلتی ہے — نہیں — مگر — برا طرح — اسی طرح — ہم — آیات کو مختلف — انداز میں — ان لوگوں کے لیے بیان کرتے ہیں — جو شکر کریں — یعنی پاکیزہ دل سے نصیحت — اور — فاسد دل سے انکار۔
۳۔ عملی سبق: اپنے دل کو پاکیزہ رکھو؛ شکر — ہدایت کا راستہ کھولتا ہے۔"""
),
1013: (
"بے شک — ہم نے نوحؑ کو — ان کی قوم کی طرف بھیجا — انہوں نے کہا — اے میری قوم — اللہ کی عبادت کرو — تمہارے لیے — اس کے علاوہ کوئی — الٰہ نہیں — بے شک — میں — تم پر — ایک بڑے دن کے عذاب سے — ڈرتا ہوں",
"""۱۔ نوحؑ کی دعوت — توحید۔
۲۔ ’’لَقَدْ أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِ فَقَالَ يَا قَوْمِ اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُ إِنِّي أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ عَظِيمٍ‘‘ — بے شک — ہم نے نوحؑ کو — ان کی قوم کی طرف بھیجا — انہوں نے کہا — اے میری قوم — اللہ کی عبادت کرو — تمہارے لیے — اس کے علاوہ کوئی — الٰہ نہیں — بے شک — میں — تم پر — ایک بڑے دن کے عذاب سے — ڈرتا ہوں — یعنی نوحؑ نے اپنی قوم کو — توحید کی طرف بلایا اور — آخرت کے عذاب سے ڈرایا۔
۳۔ عملی سبق: توحید — ہر نبی کی پہلی دعوت ہے؛ اللہ کے سوا کسی کی عبادت نہ کرو۔"""
),
1014: (
"ان کی قوم کے سرداروں نے کہا — بے شک — ہم — تمہیں — کھلی گمراہی میں — دیکھتے ہیں",
"""۱۔ قوم کے سردار — نبی کی مخالفت کا اعلان۔
۲۔ ’’قَالَ الْمَلَأُ مِن قَوْمِهِ إِنَّا لَنَرَاكَ فِي ضَلَالٍ مُّبِينٍ‘‘ — ان کی قوم کے سرداروں نے کہا — بے شک — ہم — تمہیں — کھلی گمراہی میں — دیکھتے ہیں — یعنی سردار — طاقت کے نشے میں— نبی کی دعوت کو گمراہی سمجھ کر — رد کرتے ہیں۔
۳۔ عملی سبق: حق کی مخالفت — عموماً — قدرت کے نشہ میں کی جاتی ہے؛ حق پر قائم رہو۔"""
),
}
